"""Summarize non-alerting shadow JSONL."""
import json,statistics,sys
rows=[json.loads(x) for x in open(sys.argv[1] if len(sys.argv)>1 else 'outputs/shadow_predictions.jsonl')];lat=[r.get('total_latency_seconds',r.get('total_latency',0)) for r in rows];print(json.dumps({'total_frames':len(rows),'processed_frames':sum(not r.get('dropped') for r in rows),'frames_with_vehicles':sum(bool(r.get('vehicles')) for r in rows),'positive':sum(r.get('frame_decision')=='positive' for r in rows),'negative':sum(r.get('frame_decision')=='negative' for r in rows),'uncertain':sum(r.get('frame_decision')=='uncertain' for r in rows),'gate_queue':sum(bool(r.get('gate_queue_vehicles')) for r in rows),'p50_latency':statistics.median(lat) if lat else None,'p95_latency':sorted(lat)[max(0,int(.95*len(lat))-1)] if lat else None,'error_rate':sum(bool(r.get('error')) for r in rows)/len(rows) if rows else None},indent=2))
